// ===== SafeSpend shared helpers (inlined into every Code node by build.py) =====
// Mirrors the Dart models in lib/models. Source of truth: n8n/schema/safespend.schema.json.
const DEFAULT_CATEGORIES = [{"id": "food", "name": "Food & dining", "kind": "flexible"}, {"id": "groceries", "name": "Groceries", "kind": "flexible"}, {"id": "transport", "name": "Transport", "kind": "flexible"}, {"id": "shopping", "name": "Shopping", "kind": "flexible"}, {"id": "entertainment", "name": "Entertainment", "kind": "flexible"}, {"id": "health", "name": "Health", "kind": "flexible"}, {"id": "education", "name": "Education", "kind": "flexible"}, {"id": "other", "name": "Other", "kind": "flexible"}, {"id": "rent", "name": "Rent", "kind": "fixed"}, {"id": "bills", "name": "Bills & utilities", "kind": "fixed"}, {"id": "committee", "name": "Committee (kameti)", "kind": "fixed"}, {"id": "savings", "name": "Savings", "kind": "savings"}];
